(14, 11, '_form', '[dynamichidden dynamichidden-396 \"CF7_get_post_var key=\'title\'\"]\n\n<label> Your name\n    [text* your-name autocomplete:name] </label>\n\n<label> Your email\n    [email* your-email autocomplete:email] </label>\n\n<label> Subject\n    [text* your-subject] </label>\n[text* text-857 class:modal-body]\n\n<label> Your message (optional)\n    [textarea your-message] </label>\n\n[select menu-110 include_blank \"ABCD\" \"EFGH\" \"other\"]\n\n[group abcd]\n[text other]\n[/group]\n\n[submit \"Submit\"]'),
(15, 11, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:35:\"[_site_title] <wordpress@bpssu.com>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:161:\"From: [your-name] [your-email]\nSubject: [your-subject]\n\nMessage Body:\n[your-message]\n\n-- \nThis e-mail was sent from a contact form on [_site_title] ([_site_url])\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
