(1161, 144, '_form', '<div class=\"row\">\n<h4>Your Application</h4>\n<p></p>\n<div class=\"col-lg-12 mt-20\">\n<div class=\"visitor-form__input\">\n[text* fullname placeholder \"Your name*\"]\n</div>\n</div>\n\n<div class=\"col-lg-12\">\n<div class=\"visitor-form__input\">\n[email* email-797 placeholder \"Your email*\"]\n</div>\n</div>\n<div class=\"col-lg-6\">\n<div class=\"visitor-form__input\">\n[tel* tel-551 placeholder \"Phone number*\"]\n</div>\n</div>\n<div class=\"col-lg-6\">\n<div class=\"visitor-form__input\">\n[text* experience placeholder \"Experience*\"]\n</div>\n</div>\n<div class=\"col-lg-12\">\n<div class=\"visitor-form__input\">\n<label>Job Title<span class=\"required\">*</span></label>\n[text* jobtitle id:job_title]\n</div>\n</div>\n<div class=\"col-lg-6\">\n<div class=\"visitor-form__input cv-upload\">\n<label>Upload your CV</label>\n[file* resume limit:5242880 filetypes:jpg|jpeg|pdf|docx class:form-control]\n</div>\n</div>\n<div class=\"col-lg-12\">\n<div class=\"visitor-form__input\">\n[textarea message placeholder \"Type your message\"]\n</div>\n</div>\n<div class=\"col-lg-4 col-md-4 col-12\">\n<div class=\"visit-btn mt-20\">\n[submit class:tp-btn \"Apply\"]\n</div>\n</div>\n</div>'),
