(4798, 472, '_section_title_our_value', 'field_64a4fbb027cb2'),
(4799, 472, 'value_section_excerpt', 'With over 30 years of experience in biopharmaceutical processing, our application solutions <br>offer you the flexibility you need with GMP-scalability tomorrow.'),
(4800, 472, '_value_section_excerpt', 'field_64a4fbcb27cb3'),
(4801, 472, 'value_section_content', '<h4 class=\"nabmission__title mb-35\">Trusted by some of the biggest names in the industry</h4>\r\n<p class=\"mb-35\">At Bioprocess Solutions we offer solutions, not just supplies. Our small size does not limit our scope, nor does it impact our ability to manufacture faster and cheaper than the big names in the industry. While other suppliers sell and disappear, Bioprocess Supplies’ team of designers and experts will help you every step of the way.</p>'),
(4802, 472, '_value_section_content', 'field_64a4fbeb27cb4'),
(4803, 472, 'value_section_1st_image', '133'),
(4804, 472, '_value_section_1st_image', 'field_64a4fbfd27cb5'),
