(8680, 674, 'section_title_our_process', 'Our Process'),
(8681, 674, '_section_title_our_process', 'field_64a4e8e41bec7'),
(8682, 674, 'process_section_excerpt', 'At Bioprocess Supplies we offer solutions, not just supplies. Bioprocess Supplies helps end users streamline<br> and integrate their single-use products and processes for their needs.'),
(8683, 674, '_process_section_excerpt', 'field_64a4e92a1bec8'),
(8684, 674, 'process_1_title', 'Design'),
