(9017, 725, '_choose_us_point_4_title', 'field_64a4e6954b4a9'),
(9018, 725, 'choose_us_point_4_content', 'Describe your needs and let us handle the rest! We have the industry knowledge to get the job done'),
(9019, 725, '_choose_us_point_4_content', 'field_64a4e6b34b4aa'),
(9020, 725, 'choose_us_point_4_icon', '<i class=\"flaticon-team\"></i>'),
