(9024, 725, 'section_title_our_process', 'Our Process'),
(9025, 725, '_section_title_our_process', 'field_64a4e8e41bec7'),
(9026, 725, 'process_section_excerpt', 'At Bioprocess Supplies we offer solutions, not just supplies. Bioprocess Supplies helps end users streamline<br> and integrate their single-use products and processes for their needs.'),
(9027, 725, '_process_section_excerpt', 'field_64a4e92a1bec8'),
(9028, 725, 'process_1_title', 'Design'),
(9029, 725, '_process_1_title', 'field_64a4e9631bec9'),
(9030, 725, 'process_1_content', 'Chat about your needs with our team'),
(9031, 725, '_process_1_content', 'field_64a4e9701beca'),
