INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(11027, 1403, 'process_3_content', 'Our quality system ensures consistency and compliance before shipping'),
(11028, 1403, '_process_3_content', 'field_64a4ea4ec0b87'),
(11029, 1403, 'process_3_icon', '<i class=\"flaticon-report\"></i>'),
(11030, 1403, '_process_3_icon', 'field_64a4ea5bc0b88'),
(11031, 1403, 'section_titleour_mission', 'Our Mission'),
(11032, 1403, '_section_titleour_mission', 'field_64a4f91c94c84'),
(11033, 1403, 'mission_section_excerpt', 'Your full-service manufacturer for single-use applications. Our mission is to solve<br> your bioprocessing backups and add value to the process.'),
(11034, 1403, '_mission_section_excerpt', 'field_64a4f93894c85'),
(11035, 1403, 'mission_section_content', '<h4 class=\"nabmission__title mb-35\">Our mission</h4>\r\n<p class=\"mb-35\">We aim to be more than just another supplier. Our goal is to be a valuable resource that your team can look to for answers. By sharing what we’ve learned through years of experience in the industry, we hope to improve your process and our ability to solve unique bioprocessing problems.</p>'),
(11036, 1403, '_mission_section_content', 'field_64a4fa00214e7'),
(11037, 1403, 'mission_section_1st_image', '721'),
(11038, 1403, '_mission_section_1st_image', 'field_64a4fa15214e8'),
(11039, 1403, 'mission_section_2nd_image', '722'),
(11040, 1403, '_mission_section_2nd_image', 'field_64a4fa35214e9'),
(11041, 1403, 'section_title_our_value', 'Our Value'),
(11042, 1403, '_section_title_our_value', 'field_64a4fbb027cb2'),
(11043, 1403, 'value_section_excerpt', 'With over 30 years of experience in biopharmaceutical processing, our application solutions <br>offer you the flexibility you need with GMP-scalability tomorrow.'),
(11044, 1403, '_value_section_excerpt', 'field_64a4fbcb27cb3'),
(11045, 1403, 'value_section_content', '<h4 class=\"nabmission__title mb-35\">Trusted by some of the biggest names in the industry</h4>\r\n<p class=\"mb-35\">At Bioprocess Solutions we offer solutions, not just supplies. Our small size does not limit our scope, nor does it impact our ability to manufacture faster and cheaper than the big names in the industry. While other suppliers sell and disappear, Bioprocess Supplies’ team of designers and experts will help you every step of the way.</p>'),
(11046, 1403, '_value_section_content', 'field_64a4fbeb27cb4'),
(11047, 1403, 'value_section_1st_image', '724'),
(11048, 1403, '_value_section_1st_image', 'field_64a4fbfd27cb5'),
(11049, 1403, 'value_section_2nd_image', '723'),
(11050, 1403, '_value_section_2nd_image', 'field_64a4fc0d27cb6'),
(11051, 1403, 'facility_image', '471'),
(11052, 1403, '_facility_image', 'field_651fd01973a7a'),
(11053, 1403, 'facility_text', 'Bioprocess Supplies’ home office and manufacturing site is located in the merchant square center on the\r\nedge of Red Hill, Pennsylvania. About an hour outside of Philadelphia, the building started with just 3 offices and\r\na break room in 2018. Since then, the facility has expanded to include 2 warehouses, 2 certified cleanrooms, and\r\nseveral additional office staff. The effort put in to adapt the building to clean pharmaceutical supply\r\nmanufacturing is reflected in our ability to adapt to our clients’ needs, at any size.'),
(11054, 1403, '_facility_text', 'field_651fd05873a7b'),
(11055, 1403, 'facility_title', 'The Facility'),
(11056, 1403, '_facility_title', 'field_651fd0a903eb7'),
(11057, 1403, 'quality_title', 'Quality Management'),
(11058, 1403, '_quality_title', 'field_651fd53c48cbd'),
(11059, 1403, 'quality_text', 'At Bioprocess Supplies, we strive to not only meet our customer\'s requirements but exceed them by ensuring compliance with regulatory standards and delivering high-quality products.\r\n\r\nBioprocess Supplies has a full ISO 9001 and 13485 certified Quality Management system, as well as two ISO class 7 certified cleanroom manufacturing environments.\r\n\r\nBy focusing on customer satisfaction, regulatory compliance, and product quality, Bioprocess Supplies is committed to supporting our clients with products that meet their needs and regulatory standards.'),
(11060, 1403, '_quality_text', 'field_651fd54a48cbe'),
(11061, 1403, 'quality_image', '1402'),
(11062, 1403, '_quality_image', 'field_651fd55648cbf'),
(11063, 1359, '_oembed_8225fdc9b2b063382a3736359b1fd7a8', '{{unknown}}'),
